interface.definition:
a!localVariables(
  local!selected: {},
  {
    #"SYSTEM_SYSRULES_gridField_v5"(
      label: "User Details",
      labelPosition: "ABOVE",
      data: #"SYSTEM_SYSRULES_recordData"(
        recordType: #"urn:appian:record-type:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48",
            operator: "in",
            value: ri!userid,
            applyWhen: a!isNotNullOrEmpty(ri!userid)
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48",
            operator: "not in",
            value: ri!excludeids,
            applywhen:a!isNotNullOrEmpty(ri!excludeids)
          )
        }
      ),
      showRefreshButton: true,
      showSearchBox: true,
      selectable: a!defaultValue(value:ri!selectable,default: true()),
      selectionStyle: "ROW_HIGHLIGHT",
      selectionValue: local!selected,
      selectionSaveInto: {local!selected,
      a!save(

        target: ri!select,
        value: local!selected
      )
      },
      similarityScoreThreshold: 1.0,
      columns: {
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Id",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: if(
                  fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"] < 100000,
                  text(
                    fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"],
                    "#00000"
                  ),
                  fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"]
                )
              )
            }
          ),
          sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/b9c974e1-800e-4dfe-9d43-14273008fe48"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "First Name",
          value: a!defaultValue(
            fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/432735ea-6585-464d-b6e4-77009d9bcf1d"],
            "–"
          ),
          sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/432735ea-6585-464d-b6e4-77009d9bcf1d"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Last Name",
          value: a!defaultValue(
            fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/347f4da4-04e1-4eb5-b521-564f0e8be776"],
            "–"
          ),
          sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/347f4da4-04e1-4eb5-b521-564f0e8be776"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Email",
          value: a!defaultValue(
            fv!row[#"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7e7ff32d-c4e1-468a-964f-48933b28c91e"],
            "–"
          ),
          sortField: #"urn:appian:record-field:v1:87d49c13-56b3-4601-a425-bfd5bdbef0fc/7e7ff32d-c4e1-468a-964f-48933b28c91e"
        ),

      },
      refreshAfter: "RECORD_ACTION",
      validations: {}
    )
  }
)
